import{_ as a,o as r,c as o,a2 as c}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"崩溃恢复架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/crash-recovery.md","filePath":"zh/arch/crash-recovery.md"}'),t={name:"zh/arch/crash-recovery.md"};function l(d,e,h,i,n,s){return r(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="崩溃恢复架构" tabindex="-1">崩溃恢复架构 <a class="header-anchor" href="#崩溃恢复架构" aria-label="Permalink to &quot;崩溃恢复架构&quot;">​</a></h1><h2 id="崩溃路径" tabindex="-1">崩溃路径 <a class="header-anchor" href="#崩溃路径" aria-label="Permalink to &quot;崩溃路径&quot;">​</a></h2><p><code>kernel/core/core_crash.c</code>：未处理的异常会捕获帧（寄存器、向量、故障地址、CR2/CR3 上下文），将转储打印到串口，将崩溃日志记录写入 /etc 卷，然后停止。<code>dumpinfo</code> 在重启后读取该记录；<code>crashlog</code> 列出历史记录。</p><h2 id="恐慌级隔离" tabindex="-1">恐慌级隔离 <a class="header-anchor" href="#恐慌级隔离" aria-label="Permalink to &quot;恐慌级隔离&quot;">​</a></h2><ul><li>IST1 为 #DF/#MC 提供专用栈——即使故障处理程序中发生双重故障，仍有可执行代码的位置。</li><li>异常退出路径绝不会在 IST2 上进行上下文切换（BUG-0139）。</li><li>启动自检（捕获 #DE/#UD/#PF，内核存活）在 Shell 之前运行——在任何组件信任该机制之前，其可靠性已得到验证。</li></ul><h2 id="恢复姿态" tabindex="-1">恢复姿态 <a class="header-anchor" href="#恢复姿态" aria-label="Permalink to &quot;恢复姿态&quot;">​</a></h2><p>系统本身就是自己的 WinRE：可从无磁盘的 ISO 启动，检查故障机器的卷，修复配置，重新安装启动代码（<code>install</code>/<code>abdisk</code>/<code>grub-install</code> 将其有效负载内置在内核中），从 /etc 提取日志和转储。带有救援表的恢复手册：<a href="./../manual/recovery.html">../manual/recovery.md</a>。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><code>crashtest</code>（故意引发恐慌）、<code>dumpinfo</code>（读取回数据）、回归测试套件中的崩溃日志检查，以及 E2E 硬重置场景（S12/S13）通过硬件看门狗证明了重启部分的可靠性。</p>',9)])])}const m=a(t,[["render",l]]);export{_ as __pageData,m as default};
